def clip_probe(url: str) -> dict:
    """Link metadata (title, channel, duration) through the fetch
    allowlist guard, for the quote step."""
    return clipping.fetch_info(url)


@app.function(
    image=clip_image,
    secrets=[modal.Secret.from_name("moonfactory-providers")],
    volumes={"/data": data_volume, "/worker-models": worker_models},
    cpu=4.0,
    memory=8192,
    timeout=3600,
    scaledown_window=60,
)
def process_clip_job(job_id: str):
    """Run one clip job end to end on CPU: fetch, transcribe, pick,
    render. Clips land in the library as first-class jobs (lane
    "clip") with their files already in place on the data Volume,
    so the existing file, gallery and delete routes serve them."""
    import secrets as _secrets

    job = jobs.get(job_id)
    if not job:
        return
    # A warm container's Volume view can predate the upload that
    # created this job; reload before touching any file.
    try:
        data_volume.reload()
    except Exception:
        pass
    files_dir = Path("/data/files")
    files_dir.mkdir(parents=True, exist_ok=True)
    work = Path("/data/clip-work") / job_id
    work.mkdir(parents=True, exist_ok=True)

    def set_stage(stage, status="running"):
        job["stage"] = stage
        job["status"] = status
        jobs[job_id] = job

    try:
        set_stage(CLIP_STAGES[0])
        if job.get("upload_path"):
            src = Path(job["upload_path"])
            if not src.exists():
                raise RuntimeError("the uploaded file is missing")
            title = job.get("source_title") or src.name
            uploader = ""
        else:
            info = clipping.fetch_info(job["source_url"])
            title = info.get("title") or ""
            uploader = info.get("uploader") or ""
            src = clipping.download_video(job["source_url"], work)
        info = clipping.probe(src)
        duration = float(info["duration"])
        if duration > clipping.MAX_SOURCE_SECONDS:
            raise RuntimeError("this video is longer than the 3 hour clipping limit")
        job["duration_seconds"] = round(duration, 2)
        job["source_title"] = title
        jobs[job_id] = job

        set_stage(CLIP_STAGES[1])
        wav = work / "audio.wav"
        clipping.extract_audio(src, wav)
        db = clipping.loudness_per_second(wav)
        words = []
        try:
            words = clipping.transcribe(wav, Path("/data/clip-models"))
        except Exception as exc:  # transcription never blocks clipping
            job["transcribe_error"] = str(exc)[:200]
            jobs[job_id] = job

        set_stage(CLIP_STAGES[2])
        picks, pick_info = clipping.find_clips(
            words, db, duration, title=title, uploader=uploader,
            max_clips=int(job.get("clip_count") or 3),
            length=job.get("length") or "medium",
            api_key=os.environ.get("GEMINI_API_KEY", ""),
        )
        job["pick_mode"] = pick_info.get("mode")
        job["pick_note"] = pick_info.get("note") or ""
        jobs[job_id] = job
        if not picks:
            raise RuntimeError("no clips could be picked from this video")

        set_stage(CLIP_STAGES[3])
        clip_ids = []
        for pick in picks:
            child_id = _secrets.token_hex(8)
            spec = dict(pick)
            spec["style"] = job.get("caption_style") or "bounce"
            spec["layout"] = job.get("layout") or "blur"
            clipping.render_clip(
                src, files_dir, child_id, spec, words,
                int(info["width"]), int(info["height"]),
                Path("/platform/clip_fonts"),
            )
            child = {
                "id": child_id,
                "user_id": job["user_id"],
                "worker_job_id": None,
                "provider": "clip",
                "kind": "clip_output",
                "clip_parent": job_id,
                "lane": "clip",
                "model": "clip",
                "prompt": pick.get("hook") or pick.get("title") or "Clip",
                "user_prompt": pick.get("hook") or pick.get("title") or "Clip",
                "camera_presets": [],
                "camera_preset_names": [],
                "camera_look": {},
                "status": "done",
                "error": None,
                "created_at": _now(),
                "charged_cents": 0,
                "hook": pick.get("hook") or "",
                "title": pick.get("title") or "",
                "score": pick.get("score"),
                "duration_seconds": round(pick["end"] - pick["start"], 2),
                "source_start": pick["start"],
                "source_end": pick["end"],
                "has_thumb": (files_dir / f"{child_id}.jpg").exists(),
                "bytes": (files_dir / f"{child_id}.mp4").stat().st_size,
                "plan_at_job": job.get("plan_at_job"),
                "free_tier": False,
                "music_prompt": None,
            }
            stamp_content_hash(
                child, files_dir / f"{child_id}.mp4")
            classify_job_output(
                child, files_dir / f"{child_id}.mp4")
            jobs[child_id] = child
            _index_job(child)
            clip_ids.append(child_id)
        job["clip_ids"] = clip_ids
        job["stage"] = "Done"
        job["status"] = "done"
        jobs[job_id] = job
        _clip_settle(job)
        data_volume.commit()
    except Exception as exc:  # noqa: BLE001
        job["status"] = "error"
        job["error"] = "clipping failed, nothing was charged"
        if clipping.LINK_DEAD_MESSAGE.split(". ")[0] in str(exc):
            # A dead link is the one failure the user can act on:
            # surface the working alternative, not the generic line.
            job["error"] = (clipping.LINK_DEAD_MESSAGE
                            + ". Nothing was charged")
        job["internal_error"] = str(exc)[:300]
        jobs[job_id] = job
        _clip_release_hold(job)
        data_volume.commit()


# ---------------------------------------------------------------------------
# Content fingerprints (Jack, 2026-11-24): every finished generation
# carries the SHA-256 of its stored original file on its job record
# as content_sha256, stamped by the one helper below at the moment
# the path's final file lands. A deletion tombstone keeps the
# fingerprint after the job record and its file are gone.
# ---------------------------------------------------------------------------

def stamp_content_hash(job: dict, path) -> None:
    """Stamp a finished generation's content fingerprint onto its
    job record: the SHA-256 of the canonical stored ORIGINAL file
    at `path`, the file as it landed from generation or from the
    finishing stage that assembled it. The web remux
    (<id>.web.mp4) is a derivative and is never the stamped file:
    this helper refuses such a path outright, and the remux path
    (ensure_web_file) never calls it. A hashing failure never
    blocks a delivery (the word check's rule): the error is
    logged and the job ships without the stamp. A job whose file
    is not on disk gets no stamp."""
    try:
        p = Path(path)
        if ".web." in p.name:
            return
        if not p.is_file():
            return
        digest = hashlib.sha256()
        with open(p, "rb") as fh:
            for chunk in iter(lambda: fh.read(1 << 20), b""):
                digest.update(chunk)
        job["content_sha256"] = digest.hexdigest()
        jobs[job["id"]] = job
    except Exception as exc:  # noqa: BLE001
        print(f"content hash failed for job {job.get('id')}: {exc}")


# ---------------------------------------------------------------------------
# Output classifier (Jack, 2026-11-24): a finished generation's
# public gallery listing is judged by its actual output, not only
# by its prompt. Falconsai/nsfw_image_detection (a ViT returning a
# normal/nsfw probability; code and weights Apache-2.0) runs on
# CPU at finishing, inside the finishing stage itself, and stamps
# its verdict on the job record. The verdict feeds gallery
# visibility ONLY (see gallery_visible): it never blocks creation,
# never refuses a user, never delays or blocks delivery to the
# owner, and never affects a charge. Lawful NSFW keeps generating
# and delivering exactly as before; a flagged verdict only keeps
# that one item out of the public gallery. The weights (an ONNX
# export of the published checkpoint) are cached on the models
# volume, so a cold container does not depend on Hugging Face
# being up; when they cannot be loaded the verdict stays missing
# and gallery_visible fails closed for the gallery (the job still
# delivers to its owner).
# ---------------------------------------------------------------------------

OUTPUT_CLASSIFIER_ID = "Falconsai/nsfw_image_detection"
# The one threshold: an output whose nsfw probability reaches
# this is flagged out of the public gallery.
OUTPUT_NSFW_FLAG_THRESHOLD = 0.7
# Jobs created at or after this moment are post-change jobs: with
# no verdict stamped they are not gallery eligible (fail closed).
# Jobs created before it are legacy and keep the prompt-only
# behavior they shipped under. No backfill, ever.
OUTPUT_CLASSIFIER_SINCE = 1795520000.0
OUTPUT_CLASSIFIER_DIR = Path(
    "/worker-models/classifier/falconsai-nsfw")
OUTPUT_CLASSIFIER_MAX_ATTEMPTS = 3

_output_classifier_session = None
_output_classifier_lock = threading.Lock()


def _output_classifier():
    """The lazy ONNX session for the output classifier, loaded
    once per container from the models volume. Raises when the
    weights are unavailable or the runtime is missing; the caller
    (classify_job_output) turns that into a missing verdict, never
    a blocked delivery."""
    global _output_classifier_session
    if _output_classifier_session is not None:
        return _output_classifier_session
    with _output_classifier_lock:
        if _output_classifier_session is not None:
            return _output_classifier_session
        import onnxruntime as ort

        model_path = OUTPUT_CLASSIFIER_DIR / "model.onnx"
        if not model_path.is_file():
            raise RuntimeError(
                f"output classifier weights missing at {model_path}")
        session = ort.InferenceSession(
            str(model_path), providers=["CPUExecutionProvider"])
        _output_classifier_session = session
        return session


def _classifier_preprocess(image_path):
    """One picture as the model's input tensor, following the
    published preprocessor_config.json exactly: resize to
    224x224 (bilinear), rescale by 1/255, normalize with mean and
    std 0.5."""
    import numpy as np
    from PIL import Image

    with Image.open(image_path) as img:
        img = img.convert("RGB").resize((224, 224), Image.BILINEAR)
        arr = np.asarray(img, dtype=np.float32) / 255.0
    arr = (arr - 0.5) / 0.5
    return arr.transpose(2, 0, 1)[None, :, :, :]


def _classifier_image_score(image_path, session=None) -> float:
    """The nsfw probability of one still picture."""
    import numpy as np

    session = session or _output_classifier()
    tensor = _classifier_preprocess(image_path)
    logits = session.run(None, {"pixel_values": tensor})[0][0]
    exp = np.exp(logits - float(np.max(logits)))
    probs = exp / float(np.sum(exp))
    return float(probs[1])


def _video_sample_times(duration) -> list:
    """Up to three sample points in a finished video: the first
    moment, the middle, and the last moment. A short video's
    points collapse onto each other and are deduped, so a very
    short clip may only yield one or two distinct samples."""
    try:
        d = float(duration or 0)
    except (TypeError, ValueError):
        d = 0.0
    if d <= 0:
        return [0.0]
    times = [min(0.5, d / 2.0), d / 2.0, max(d - 0.5, 0.0)]
    out = []
    for t in times:
        if all(abs(t - seen) > 0.25 for seen in out):
            out.append(round(t, 3))
    return out


def _classifier_video_scores(video_path, session=None) -> list:
    """The nsfw probabilities of a finished video's sampled
    frames (first, middle, last). Raises when no frame could be
    read at all: an unjudged video is a missing verdict, not a
    clean one."""
    session = session or _output_classifier()
    duration = 0.0
    try:
        probe = subprocess.run(
            ["ffprobe", "-v", "error", "-show_entries",
             "format=duration", "-of", "json", str(video_path)],
            capture_output=True, timeout=60)
        duration = float(json.loads(
            probe.stdout.decode() or "{}").get(
                "format", {}).get("duration") or 0)
    except Exception:  # noqa: BLE001
        duration = 0.0
    scores = []
    with tempfile.TemporaryDirectory() as tmp:
        for i, t in enumerate(_video_sample_times(duration)):
            frame = Path(tmp) / f"frame{i}.jpg"
            try:
                subprocess.run(
                    ["ffmpeg", "-y", "-ss", str(t), "-i",
                     str(video_path), "-vframes", "1", "-q:v", "3",
                     str(frame)],
                    capture_output=True, timeout=120)
            except Exception:  # noqa: BLE001
                continue
            if frame.is_file() and frame.stat().st_size > 0:
                scores.append(_classifier_image_score(frame, session))
    if not scores:
        raise RuntimeError("no video frame could be sampled")
    return scores


def _classifier_file_scores(path) -> list:
    """Every nsfw probability a finished file earns: one for a
    still image, one per sampled frame for a video. The caller
    takes the maximum, so a video is judged by its worst sampled
    frame."""
    p = Path(path)
    suffix = p.suffix.lower()
    if suffix == ".mp4":
        return _classifier_video_scores(p)
    if suffix in (".png", ".jpg", ".jpeg", ".webp"):
        return [_classifier_image_score(p)]
    return []


def classify_job_output(job: dict, path=None) -> None:
    """Stamp the output classifier's verdict onto a finished
    job's record: output_nsfw_score (the worst probability the
    file earned), output_flagged (the score reached
    OUTPUT_NSFW_FLAG_THRESHOLD), output_classifier (the model
    id), output_classified_at. Called from the finishing stages
    beside stamp_content_hash, over the same final file.

    The verdict is gallery-only. A failure (weights unavailable,
    inference error, no readable frame) never blocks, delays or
    changes the delivery: it is logged, an error stamp and an
    attempt count are recorded, and the job simply carries no
    verdict, which gallery_visible treats as not gallery
    eligible for post-change jobs. Attempts are capped so a
    permanently unavailable model is not retried on every read;
    a later success clears the error stamp."""
    try:
        if job.get("output_nsfw_score") is not None:
            return
        if int(job.get("output_classifier_attempts") or 0) \
                >= OUTPUT_CLASSIFIER_MAX_ATTEMPTS:
            return
        if path is None:
            path = FILES_DIR / (
                f"{job['id']}.png" if job.get("kind") == "image"
                else f"{job['id']}.mp4")
        p = Path(path)
        if ".web." in p.name or not p.is_file():
            return
        scores = _classifier_file_scores(p)
        if not scores:
            return
        score = max(scores)
        job["output_nsfw_score"] = round(score, 4)
        job["output_flagged"] = bool(
            score >= OUTPUT_NSFW_FLAG_THRESHOLD)
        job["output_classifier"] = OUTPUT_CLASSIFIER_ID
        job["output_classified_at"] = _now()
        job.pop("output_classifier_error", None)
        # The gallery thumb derives at finishing beside the
        # verdict (perf pass, 2026-11-24), best-effort: the
        # thumb routes derive it lazily if this did not land.
        ensure_gallery_thumb(job, p)
        jobs[job["id"]] = job
    except Exception as exc:  # noqa: BLE001
        try:
            job["output_classifier_attempts"] = int(
                job.get("output_classifier_attempts") or 0) + 1
            job["output_classifier"] = OUTPUT_CLASSIFIER_ID
            job["output_classified_at"] = _now()
            job["output_classifier_error"] = str(exc)[:300]
            jobs[job["id"]] = job
        except Exception:  # noqa: BLE001
            pass
        print(f"output classifier failed for job "
              f"{job.get('id')}: {exc}")


# ---------------------------------------------------------------------------
# Gallery thumbnails (perf pass, Jack, 2026-11-24): the gallery
# grid and the studio cards used to download finished originals
# (a 1.3 MB PNG for one image card) just to show a small tile.
# Every finished job gets a small JPEG derivative, at most
# GALLERY_THUMB_WIDTH px wide, cached on the data volume beside
# its files as {job_id}.gthumb.jpg. New jobs derive theirs at
# finishing (ensure_gallery_thumb is called from the finishing
# stages beside classify_job_output); existing jobs derive
# theirs the first time a thumb is requested. Derivation is
# best-effort: a failure returns None and callers fall back to
# the routes they already had.
GALLERY_THUMB_WIDTH = 480


def ensure_gallery_thumb(job: dict, path=None):
    """The job's small preview JPEG, derived and cached on
    first need. Returns the Path, or None when no derivative
    can be made from the finished file."""
    try:
        thumb = FILES_DIR / f"{job['id']}.gthumb.jpg"
        if thumb.exists() and thumb.stat().st_size > 0:
            return thumb
        if path is None:
            path = FILES_DIR / (
                f"{job['id']}.png" if job.get("kind") == "image"
                else f"{job['id']}.mp4")
        p = Path(path)
        if ".web." in p.name or not p.is_file():
            return None
        FILES_DIR.mkdir(parents=True, exist_ok=True)
        tmp = FILES_DIR / f"{job['id']}.gthumb.tmp.jpg"
        try:
            tmp.unlink(missing_ok=True)
        except Exception:
            pass
        cmd = ["ffmpeg", "-y"]
        if job.get("kind") != "image":
            cmd += ["-ss", "0.5"]
        cmd += ["-i", str(p), "-vframes", "1",
                "-vf", f"scale='min({GALLERY_THUMB_WIDTH},iw)':-2",
                "-q:v", "5", str(tmp)]
        proc = subprocess.run(cmd, capture_output=True,
                              timeout=120)
        if proc.returncode != 0 or not tmp.exists() \
                or tmp.stat().st_size == 0:
            try:
                tmp.unlink(missing_ok=True)
            except Exception:
                pass
            return None
        tmp.replace(thumb)
        return thumb
    except Exception:  # noqa: BLE001
        return None


# ---------------------------------------------------------------------------
# Input classifier (Jack, 2026-11-24): the output classifier's
# model also judges the still pictures a job takes IN at
# creation — the uploaded start and end frames, an edit lane's
# source picture, and reference pictures carried as data URLs —
# everywhere the platform actually holds the picture's bytes at
# creation. The verdict stamps the job record (input_nsfw_score,
# input_flagged, input_classifier, input_classified_at) and has
# exactly two effects, split by lane:
#
# - On a REGULAR lane it is a creation gate: a flagged upload
#   refuses creation before any charge, hold or dispatch, and
#   an upload set that could not be judged refuses too (fail
#   closed — an unjudged upload does not generate on a regular
#   lane). The refusal is a lane-fit refusal, not an
#   illegal-content refusal: it writes no record to
#   moonfactory-refusals and never touches the suspension
#   ladder; it is logged in the app log only.
# - On an UNCENSORED lane it never refuses: legal NSFW is the
#   lane's purpose, the verdict stamps, and the gallery bars
#   (the uncensored image-input bar and the verdict bar in
#   gallery_visible) do the rest.
#
# Remote reference URLs (http/https) are never fetched at
# creation, so they are never judged: a job whose only inputs
# ride as remote URLs carries no input verdict at all. A job
# with no input verdict is judged for the gallery by the other
# signals alone — the input side never fails the gallery
# closed, deliberately unlike the output side, whose verdict
# gates new jobs' listing.
# ---------------------------------------------------------------------------

INPUT_REFUSAL_FLAGGED = (
    "This image can not be used with this model. "
    "The uncensored models can work with images like this.")
INPUT_REFUSAL_UNJUDGED = (
    "We could not check that image just now. "
    "Try uploading it again.")


def _classifier_bytes_score(data: bytes, session=None) -> float:
    """The nsfw probability of one picture held as bytes: it is
    written to a scratch file and read by the same scoring seam
    the finished-file verdicts use."""
    with tempfile.NamedTemporaryFile(
            suffix=".png", delete=False) as fh:
        fh.write(data)
        tmp_path = fh.name
    try:
        return _classifier_image_score(tmp_path, session)
    finally:
        try:
            os.unlink(tmp_path)
        except OSError:
            pass


def _input_image_bytes(b64_images=(), data_urls=()) -> list:
    """Decode the judgeable input pictures a create call holds
    as bytes: raw base64 pictures (the uploaded start and end
    frames) and data URLs (an edit lane's source, a drama
    entity's uploaded picture, a bare base64 picture riding a
    reference list in the drama carry frame's shape). Remote
    http(s) URLs are skipped, never fetched. A payload that
    does not decode raises: a picture that cannot be read
    cannot be judged, and the caller stamps the set unjudged
    rather than guessing."""
    out = []
    for raw in b64_images or ():
        if raw:
            out.append(base64.b64decode(raw))
    for raw in data_urls or ():
        if not raw or not isinstance(raw, str):
            continue
        if raw.startswith("data:image/"):
            payload = raw.split(",", 1)[1] if "," in raw else ""
            out.append(base64.b64decode(payload))
        elif "://" not in raw and len(raw) > 200:
            out.append(base64.b64decode(raw))
    return out


def classify_input_images(b64_images=(), data_urls=()):
    """Judge the still pictures a job takes in at creation,
    with the output classifier's model and threshold. Returns
    None when the job carries no judgeable input picture at
    all (no uploads, or only remote reference URLs). Otherwise
    a verdict dict: {"score": the worst probability across
    every input picture, "flagged": the score reached
    OUTPUT_NSFW_FLAG_THRESHOLD} — the max governs, the same
    rule as a video's sampled frames. When any one picture
    could not be judged (weights unavailable, an unreadable
    picture), the verdict is {"score": None, "error": ...}:
    one unjudged picture leaves the whole set unjudged, never
    a partial clean."""
    try:
        pictures = _input_image_bytes(b64_images, data_urls)
    except Exception as exc:  # noqa: BLE001
        return {"score": None,
                "error": f"input decode failed: {exc}"[:300]}
    if not pictures:
        return None
    try:
        session = _output_classifier()
        score = max(
            _classifier_bytes_score(picture, session)
            for picture in pictures)
    except Exception as exc:  # noqa: BLE001
        return {"score": None, "error": str(exc)[:300]}
    return {"score": round(float(score), 4),
            "flagged": bool(
                score >= OUTPUT_NSFW_FLAG_THRESHOLD)}


def stamp_input_verdict(job: dict, verdict) -> None:
    """Carry a classify_input_images verdict onto the job
    record: input_nsfw_score, input_flagged, input_classifier,
    input_classified_at — or, for an unjudged set,
    input_classifier_error in place of a score. A None verdict
    (the job took no judgeable picture in) stamps nothing."""
    if verdict is None:
        return
    job["input_classifier"] = OUTPUT_CLASSIFIER_ID
    job["input_classified_at"] = _now()
    if verdict.get("error"):
        job["input_classifier_error"] = verdict["error"]
        print(f"input classifier failed for job "
              f"{job.get('id')}: {verdict['error']}")
    else:
        job["input_nsfw_score"] = verdict["score"]
        job["input_flagged"] = verdict["flagged"]


def input_gate_refusal(probe: dict, verdict):
    """The creation refusal for uploads (Jack, 2026-11-24),
    as the user-facing message to refuse with, or None when
    creation proceeds. On a REGULAR lane a flagged upload
    refuses, and an unjudged upload set refuses too (fail
    closed). On an uncensored lane neither ever refuses.
    `probe` is any dict job_is_uncensored reads — the
    model/lane pair is enough — so the split follows the
    platform's one standing definition of the uncensored
    scope. The refusal is logged here, in the app log only:
    no refusal record, no suspension count, ever."""
    if verdict is None or job_is_uncensored(probe):
        return None
    if verdict.get("error"):
        print(f"input gate refused a regular-lane creation "
              f"(model {probe.get('model') or probe.get('lane')}): "
              f"unjudged upload: {verdict['error']}")
        return INPUT_REFUSAL_UNJUDGED
    if verdict.get("flagged"):
        print(f"input gate refused a regular-lane creation "
              f"(model {probe.get('model') or probe.get('lane')}): "
              f"flagged upload")
        return INPUT_REFUSAL_FLAGGED
    return None


# ---------------------------------------------------------------------------
# Profile photos (Jack, 2026-11-24): an account can carry one
# profile photo, uploaded from the Account dialog, shown in the
# header avatar, the dialog itself, and beside the creator
# handle on gallery cards — everywhere the handle shows, and
# nowhere else. The upload is processed on the server: it must
# be a real picture (decoded and re-encoded, never trusted as
# sent), center cropped to a square, and no larger than 256 by
# 256, stored as one JPEG per account on the data volume, a new
# upload replacing the old file. Before anything is stored the
# picture runs through the same input classifier as a regular
# lane upload, with the same fail closed rule: a flagged photo
# is refused and never stored or shown, and a photo that could
# not be judged is refused too. Removing the photo deletes the
# file and returns the account to its initial letter.
# ---------------------------------------------------------------------------

PROFILE_PHOTO_SIZE = 256
PROFILE_PHOTO_MAX_BYTES = 10 * 1024 * 1024
PROFILE_PHOTO_MAX_PIXELS = 64 * 1000 * 1000
PROFILE_PHOTO_FLAGGED = (
    "That photo can not be used as a profile photo.")
PROFILE_PHOTO_UNJUDGED = (
    "We could not check that photo just now. "
    "Try uploading it again.")
PROFILE_PHOTO_NOT_IMAGE = (
    "That file is not a picture we can use.")
PROFILE_PHOTO_TOO_LARGE = "That photo file is too large."

# ---------------------------------------------------------------------------
# Legal acceptance at sign-up (Jack, 2026-11-24). Creating an
# account requires accepting the Terms of Service, the Privacy
# Policy, and the Acceptable Use Policy, and confirming the age
# floor from the Terms. The sign-in form carries an acceptance
# checkbox that starts unchecked; the sign-up endpoint refuses
# any create that does not carry the acceptance, whatever the
# client sent, and a successful sign-up stamps the account with
# when it accepted and which legal pack it accepted.
# LEGAL_VERSION names the current pack by the date the Terms
# page itself carries (Last updated November 23, 2026). Existing
# accounts are untouched: no retroactive prompt, no backfill.
# ---------------------------------------------------------------------------

LEGAL_VERSION = "2026-11-23"
LEGAL_ACCEPTANCE_REQUIRED = (
    "Please accept the Terms of Service, the Privacy Policy, "
    "and the Acceptable Use Policy to create your account.")


def legal_acceptance_stamp(body):
    """The acceptance record a sign-up body carries, or None
    when the sign-up did not accept. Only a true accept_terms
    counts; anything else is no acceptance."""
    if not isinstance(body, dict) or body.get("accept_terms") is not True:
        return None
    return {"accepted_at": _now(), "legal_version": LEGAL_VERSION}


# ---------------------------------------------------------------------------
# Acceptance log (Jack, 2026-11-24): every checkbox a user
# ticks that carries legal weight leaves a record here, kept
# for the platform's own evidence. The log is append only: a
# dedicated Dict keyed by user id holds that account's events
# in order, an event is only ever appended, and no code path
# edits or deletes an entry. The fast stamp fields on the
# user record (terms_accepted_at, legal_version,
# adult_confirmed_at) stay exactly as they are and stay what
# the gates read; this log is the evidence trail behind them.
# Only real acceptances are recorded: a refused, unchecked,
# or failed attempt writes nothing.
# ---------------------------------------------------------------------------

ACCEPTANCE_SIGNUP_LEGAL = "signup_legal"
ACCEPTANCE_ADULT_18_PLUS = "adult_18_plus"


def record_acceptance(user, kind, legal_version=None):
    """Append one acceptance event for an account and return
    it. The entry carries the user id, the account email as it
    stands at the moment of acceptance, the event kind, the
    legal version where one applies, and the server time. A
    failed write is logged to the app log and never raised:
    the acceptance itself already happened and its stamp is
    on the user record."""
    entry = {
        "user_id": (user or {}).get("id"),
        "email": (user or {}).get("email"),
        "kind": kind,
        "legal_version": legal_version,
        "at": _now(),
    }
    try:
        events = list(acceptances.get(user["id"]) or [])
        events.append(entry)
        acceptances[user["id"]] = events
    except Exception as exc:  # noqa: BLE001
        print(f"acceptance log write failed: {exc}")
    return entry


def profile_photo_path(user_id: str) -> Path:
    """The one stored profile photo for an account."""
    return FILES_DIR / "avatars" / f"{user_id}.jpg"


def process_profile_photo(data: bytes) -> bytes:
    """Normalize an uploaded profile photo to its stored form:
    the picture decoded for real (a file that does not decode
    raises ValueError), EXIF orientation applied, center
    cropped to a square, downscaled to at most PROFILE_PHOTO_SIZE
    on a side, and returned as JPEG bytes. Oversized pixel
    counts raise too, so a decompression bomb never gets
    decoded at full size more than once."""
    import io

    from PIL import Image, ImageOps

    try:
        with Image.open(io.BytesIO(data)) as probe:
            width, height = probe.size
            if width * height > PROFILE_PHOTO_MAX_PIXELS:
                raise ValueError("too many pixels")
            probe.verify()
        with Image.open(io.BytesIO(data)) as img:
            img = ImageOps.exif_transpose(img).convert("RGB")
            width, height = img.size
            side = min(width, height)
            left = (width - side) // 2
            top = (height - side) // 2
            img = img.crop((left, top, left + side, top + side))
            if side > PROFILE_PHOTO_SIZE:
                img = img.resize(
                    (PROFILE_PHOTO_SIZE, PROFILE_PHOTO_SIZE),
                    Image.LANCZOS)
            out = io.BytesIO()
            img.save(out, "JPEG", quality=88)
            return out.getvalue()
    except ValueError:
        raise
    except Exception as exc:  # noqa: BLE001
        raise ValueError(f"unreadable picture: {exc}") from exc


def profile_photo_refusal(verdict):
    """The refusal message for a profile photo's classifier
    verdict, or None when the photo may be stored. The photo is
    a public picture, so it is judged like a regular lane
    upload: flagged refuses, and unjudged refuses too (fail
    closed). A None verdict cannot come back from a one
    picture call, but it is treated as unjudged if it ever
    does, never as clean."""
    if verdict is None or verdict.get("error"):
        return PROFILE_PHOTO_UNJUDGED
    if verdict.get("flagged"):
        return PROFILE_PHOTO_FLAGGED
    return None


def judge_profile_photo(data: bytes):
    """Process an uploaded profile photo and judge the exact
    bytes that will be stored, returning (jpeg, verdict). The
    classifier sees the normalized 256x256 JPEG, never the raw
    upload: the public picture is the picture that gets judged,
    and a multi-megabyte phone photo never reaches the model
    at full size. Raises ValueError when the upload does not
    decode as a real picture. Both halves are synchronous CPU
    work, so the endpoint runs this in the threadpool, off the
    event loop: judging a full size phone photo inline once
    hung the request until the phone webview gave up on it
    (Jack's "Load failed", 2026-11-24)."""
    jpeg = process_profile_photo(data)
    verdict = classify_input_images(
        b64_images=[base64.b64encode(jpeg).decode()])
    return jpeg, verdict


def save_profile_photo_file(user_id: str, jpeg: bytes) -> Path:
    """Write the account's stored profile photo atomically: a
    temp file beside the destination, replaced into place, so
    a reader never sees a half written photo."""
    dest = profile_photo_path(user_id)
    dest.parent.mkdir(parents=True, exist_ok=True)
    tmp = dest.with_suffix(".tmp.jpg")
    tmp.write_bytes(jpeg)
    tmp.replace(dest)
    return dest


def write_job_tombstone(job: dict) -> None:
    """Retain the minimal deletion tombstone for a job about to
    be deleted, so its content fingerprint survives the job
    record and the file: job id, account id, creation timestamp,
    model/lane, and the fingerprint. Only a stamped job leaves
    one. The tombstone carries no file, no prompt text, and no
    other content, lives in its own Dict beside the job records,
    and is never exposed in any user-facing or public payload."""
    try:
        digest = job.get("content_sha256")
        if not digest:
            return
        tombstones[job["id"]] = {
            "id": job["id"],
            "user_id": job.get("user_id"),
            "created_at": job.get("created_at"),
            "model": job.get("model") or job.get("image_model"),
            "lane": job.get("lane") or job.get("image_model"),
            "content_sha256": digest,
        }
    except Exception as exc:  # noqa: BLE001
        print(f"tombstone failed for job {job.get('id')}: {exc}")


def place_legal_hold(job: dict, trigger: str, note: str = "") -> None:
    """Place a legal hold on a job removed or confirmed-flagged
    for illegal content: the FULL case file is retained, the
    18 U.S.C. 2258A(b) report set, in its own Dict. Kept: a
    complete copy of the job record (the prompt as typed, the
    model and lane, every timestamp, the input flags such as
    has_start_image, the charge data, and the creating request's
    IP), the account identifiers the user record holds (user id,
    email, signup timestamp, plan), the content fingerprint, an
    action log (what triggered the hold, when, and what was done,
    with fields for the CyberTipline report number and the NCMEC
    confirmation date, filled when a report is filed), and the
    ids of the account's other jobs, flagged for hold review.
    A repeat call appends to the action log instead of replacing
    the case file, so a restore never evaporates the record.
    Hold records live outside the jobs Dict, are exempt from
    ordinary user deletion, and are never exposed in any
    user-facing or public payload. A hold failure never blocks
    the removal that triggered it. Placing a hold also runs the
    automated vault export (see _legal_hold_vault_export): the
    case material seals itself into the private vault bucket
    with no human step, and on a removal the verified export
    takes the plaintext off this volume."""
    try:
        if job.get("status") == "done" \
                and not job.get("content_sha256"):
            # The case file carries the fingerprint even when
            # the job's own finishing hook never ran for it:
            # stamp from the stored original first.
            stamp_content_hash(
                job, FILES_DIR / (f"{job['id']}.png"
                                  if job.get("kind") == "image"
                                  else f"{job['id']}.mp4"))
        try:
            job_copy = json.loads(json.dumps(job, default=str))
        except Exception:
            job_copy = dict(job)
        owner = users.get(f"id:{job.get('user_id')}")
        account = {}
        if owner:
            account = {
                "user_id": owner.get("id"),
                "email": owner.get("email"),
                "created_at": owner.get("created_at"),
                "plan": owner.get("plan"),
                "handle": owner.get("handle"),
                "verified": owner.get("verified"),
            }
        # Sibling ids come off the owner's index entry (perf
        # pass 3) instead of a whole-store walk.
        siblings = [
            e[0] for e in (
                _user_job_index(job.get("user_id")).get("ids")
                or [])
            if e[0] != job.get("id")]
        existing = legal_holds.get(job["id"]) or {}
        actions = list(existing.get("actions") or [])
        actions.append({
            "action": "hold placed",
            "trigger": trigger,
            "note": note or None,
            "at": _now(),
        })
        legal_holds[job["id"]] = {
            "job_id": job["id"],
            "held_at": existing.get("held_at") or _now(),
            "trigger": trigger,
            "job": job_copy,
            "account": account,
            "content_sha256": job.get("content_sha256"),
            "actions": actions,
            "cybertipline_report_number":
                existing.get("cybertipline_report_number"),
            "ncmec_confirmation_date":
                existing.get("ncmec_confirmation_date"),
            "sibling_job_ids": siblings,
            "vault": existing.get("vault"),
            "destruction_state":
                existing.get("destruction_state") or "pending",
            "law_enforcement_hold":
                bool(existing.get("law_enforcement_hold")),
            "content_destroyed_at":
                existing.get("content_destroyed_at"),
        }
        # The automated vault export: the case material seals
        # itself into the private R2 vault, and on a removal the
        # verified export takes the plaintext off this volume.
        # It never raises and never blocks the removal that
        # placed the hold.
        _legal_hold_vault_export(
            job,
            remove_plaintext=(trigger == "admin_gallery_remove"))
    except Exception as exc:  # noqa: BLE001
        print(f"legal hold failed for job {job.get('id')}: {exc}")


# ---------------------------------------------------------------------------
# Automated legal-hold vault (Jack, 2026-11-24: "I want it
# automated, I don't wanna have to do anything"). When a legal
# hold is placed, the case material leaves this app by itself:
# the original file and a JSON copy of the case record are sealed
# under the vault public key (PyNaCl SealedBox) and uploaded to
# the dedicated private Cloudflare R2 bucket below. Ciphertext
# is the only thing that ever leaves the app. The matching
# private key sits in the moonfactory-providers Modal secret and
# is NEVER read by this app, so even a compromised app cannot
# decrypt the vault; decryption happens offline, only if law
# enforcement ever needs the material. Once an upload is
# verified by readback, a removal-triggered hold deletes the
# plaintext from the data volume, so no readable copy stays on
# Modal. A daily sweep destroys vaulted content once its
# one-year preservation period (18 U.S.C. 2258A(h), as extended
# by the REPORT Act of 2024) has run, provided a CyberTipline
# confirmation date is on the record and no law-enforcement hold
# flag is set; the case record (the log) is retained after the
# content is destroyed. A failed export never loses material:
# the hold stands, the plaintext stays, and the failure is
# written into the hold's action log.
# ---------------------------------------------------------------------------

LEGAL_HOLD_VAULT_BUCKET = "moonfactory-legal-holds"
LEGAL_HOLD_VAULT_PUBLIC_KEY = \
    "e/4t/ns06gyW6El3HblluZ/0bar82GSSMF2ru6TtYFA="
LEGAL_HOLD_ENCRYPTION = (
    "PyNaCl SealedBox (XSalsa20-Poly1305), per-object ephemeral key")


def _vault_seal(data: bytes) -> bytes:
    """Seal bytes for the legal-hold vault under the vault public
    key. A SealedBox is anonymous with a per-message ephemeral
    key: only the holder of the private key (in the Modal secret,
    never in this app) can open the result."""
    from nacl.public import PublicKey, SealedBox

    box = SealedBox(PublicKey(
        base64.b64decode(LEGAL_HOLD_VAULT_PUBLIC_KEY)))
    return box.encrypt(data)


def _vault_object_url(key: str) -> str:
    account = os.environ.get("CLOUDFLARE_ACCOUNT_ID", "")
    if not account:
        raise RuntimeError("legal hold vault: no Cloudflare account id")
    return ("https://api.cloudflare.com/client/v4/accounts/"
            f"{account}/r2/buckets/{LEGAL_HOLD_VAULT_BUCKET}"
            f"/objects/{key}")


def _vault_headers() -> dict:
    token = os.environ.get("LEGAL_HOLD_R2_TOKEN", "")
    if not token:
        raise RuntimeError("legal hold vault: no R2 token configured")
    return {"Authorization": f"Bearer {token}"}


def _vault_put(key: str, data: bytes) -> int:
    """Upload ciphertext to the vault bucket and verify it by
    readback: a streaming GET whose Content-Length must equal
    the uploaded length. Returns the verified size. Raises on
    any mismatch, so a caller never treats an unverified upload
    as stored."""
    import requests

    url = _vault_object_url(key)
    resp = requests.put(url, headers=_vault_headers(), data=data,
                        timeout=300)
    if resp.status_code != 200:
        raise RuntimeError(
            f"legal hold vault: PUT {key} answered {resp.status_code}")
    with requests.get(url, headers=_vault_headers(), stream=True,
                      timeout=300) as got:
        if got.status_code != 200:
            raise RuntimeError(
                f"legal hold vault: readback of {key} answered "
                f"{got.status_code}")
        size = int(got.headers.get("Content-Length") or -1)
    if size != len(data):
        raise RuntimeError(
            f"legal hold vault: readback size {size} != uploaded "
            f"{len(data)} for {key}")
    return size


def _vault_size(key: str):
    """The stored size of a vault object, or None when it is not
    there. A streaming GET reads only the headers."""
    import requests

    with requests.get(_vault_object_url(key),
                      headers=_vault_headers(), stream=True,
                      timeout=120) as got:
        if got.status_code == 404:
            return None
        if got.status_code != 200:
            raise RuntimeError(
                f"legal hold vault: size check of {key} answered "
                f"{got.status_code}")
        return int(got.headers.get("Content-Length") or -1)


def _vault_delete(key: str) -> None:
    """Delete a vault object and verify it is gone."""
    import requests

    url = _vault_object_url(key)
    resp = requests.delete(url, headers=_vault_headers(), timeout=120)
    if resp.status_code not in (200, 204):
        raise RuntimeError(
            f"legal hold vault: DELETE {key} answered "
            f"{resp.status_code}")
    if _vault_size(key) is not None:
        raise RuntimeError(
            f"legal hold vault: {key} still present after DELETE")


def _legal_hold_vault_export(job: dict, remove_plaintext: bool) -> None:
    """The automated export half of a legal hold (see the vault
    block above). Runs inside place_legal_hold and never raises:
    any failure is written into the hold's action log and leaves
    every plaintext byte exactly where it was."""
    job_id = job.get("id")
    uploaded = []
    try:
        hold = legal_holds.get(job_id)
        if not hold:
            return
        original = FILES_DIR / (
            f"{job_id}.png" if job.get("kind") == "image"
            else f"{job_id}.mp4")
        file_bytes = None
        if original.is_file():
            file_bytes = original.read_bytes()
        record_payload = json.dumps({
            "job": hold.get("job"),
            "account": hold.get("account"),
            "content_sha256": hold.get("content_sha256"),
            "held_at": hold.get("held_at"),
            "trigger": hold.get("trigger"),
            "sibling_job_ids": hold.get("sibling_job_ids"),
            "cybertipline_report_number":
                hold.get("cybertipline_report_number"),
            "ncmec_confirmation_date":
                hold.get("ncmec_confirmation_date"),
        }, default=str).encode()
        content_key = None
        content_size = None
        if file_bytes is not None:
            content_key = f"holds/{job_id}/content.enc"
            content_size = _vault_put(content_key,
                                      _vault_seal(file_bytes))
            uploaded.append(content_key)
        record_key = f"holds/{job_id}/record.enc"
        record_size = _vault_put(record_key,
                                 _vault_seal(record_payload))
        uploaded.append(record_key)
        hold = legal_holds.get(job_id) or hold
        actions = list(hold.get("actions") or [])
        if file_bytes is None:
            actions.append({
                "action": "vault export: records only",
                "note": "the original file was already gone when "
                        "the hold was placed",
                "at": _now(),
            })
        actions.append({
            "action": "vault export",
            "bucket": LEGAL_HOLD_VAULT_BUCKET,
            "content_key": content_key,
            "content_bytes": content_size,
            "record_key": record_key,
            "record_bytes": record_size,
            "at": _now(),
        })
        hold["vault"] = {
            "bucket": LEGAL_HOLD_VAULT_BUCKET,
            "content_key": content_key,
            "record_key": record_key,
            "content_sha256": hold.get("content_sha256"),
            "encryption": LEGAL_HOLD_ENCRYPTION,
            "exported_at": _now(),
        }
        hold["actions"] = actions
        legal_holds[job_id] = hold
        if remove_plaintext and file_bytes is not None:
            for path in (FILES_DIR / f"{job_id}.mp4",
                         FILES_DIR / f"{job_id}.web.mp4",
                         FILES_DIR / f"{job_id}.raw.mp4",
                         FILES_DIR / f"{job_id}.png",
                         FILES_DIR / f"{job_id}.jpg",
                         FILES_DIR / "beds" / f"{job_id}.wav"):
                try:
                    path.unlink(missing_ok=True)
                except Exception:
                    pass
            data_volume.commit()
            hold = legal_holds.get(job_id) or hold
            actions = list(hold.get("actions") or [])
            actions.append({
                "action": "plaintext removed from the platform "
                          "volume after verified vault export",
                "at": _now(),
            })
            hold["actions"] = actions
            legal_holds[job_id] = hold
    except Exception as exc:  # noqa: BLE001
        print(f"legal hold vault export failed for job {job_id}: {exc}")
        try:
            hold = legal_holds.get(job_id)
            if hold:
                actions = list(hold.get("actions") or [])
                actions.append({
                    "action": "vault export failed",
                    "error": str(exc)[:300],
                    "partial_upload_keys": uploaded or None,
                    "note": "plaintext left in place; nothing deleted",
                    "at": _now(),
                })
                hold["actions"] = actions
                legal_holds[job_id] = hold
        except Exception:
            pass


def _hold_destruction_due(hold: dict, today) -> bool:
    """Whether a hold's vaulted content is due for destruction:
    a CyberTipline confirmation date is on the record, vaulted
    content exists, the destruction state is still pending, no
    law-enforcement hold flag is set, and today is past the
    confirmation date plus one year (the 2258A(h) preservation
    period). Holds without a confirmation date are never due."""
    if not hold or hold.get("law_enforcement_hold"):
        return False
    if not hold.get("vault"):
        return False
    if hold.get("destruction_state") != "pending":
        return False
    conf = hold.get("ncmec_confirmation_date")
    if not conf:
        return False
    try:
        conf_date = datetime.date.fromisoformat(str(conf)[:10])
    except ValueError:
        return False
    try:
        due = conf_date.replace(year=conf_date.year + 1)
    except ValueError:
        # A February 29 confirmation runs to February 28.
        due = conf_date.replace(year=conf_date.year + 1, day=28)
    return today > due


def sweep_legal_hold_destructions(today=None) -> list:
    """Destroy the vaulted content of every due hold (see
    _hold_destruction_due): both ciphertext objects are deleted
    and each deletion verified, the destruction is appended to
    the hold's action log with its CyberTipline report number,
    and the hold RECORD (the case log) is retained. A failure on
    one hold is logged on that hold and never stops the sweep."""
    if today is None:
        today = datetime.datetime.now(datetime.timezone.utc).date()
    destroyed = []
    for key in list(legal_holds.keys()):
        hold = legal_holds.get(key)
        if not _hold_destruction_due(hold, today):
            continue
        try:
            vault = hold.get("vault") or {}
            for obj_key in (vault.get("content_key"),
                            vault.get("record_key")):
                if obj_key:
                    _vault_delete(obj_key)
            actions = list(hold.get("actions") or [])
            actions.append({
                "action": "vault content destroyed",
                "method": "deletion of the encrypted vault "
                          "objects (R2), verified by readback",
                "cybertipline_report_number":
                    hold.get("cybertipline_report_number"),
                "at": _now(),
            })
            hold["actions"] = actions
            hold["destruction_state"] = "destroyed"
            hold["content_destroyed_at"] = _now()
            legal_holds[key] = hold
            destroyed.append(key)
        except Exception as exc:  # noqa: BLE001
            print(f"legal hold destruction failed for {key}: {exc}")
            try:
                hold = legal_holds.get(key) or hold
                actions = list(hold.get("actions") or [])
                actions.append({
                    "action": "vault destruction failed",
                    "error": str(exc)[:300],
                    "at": _now(),
                })
                hold["actions"] = actions
                legal_holds[key] = hold
            except Exception:
                pass
    return destroyed


@app.function(
    image=image,
    secrets=[modal.Secret.from_name("moonfactory-providers")],
    schedule=modal.Period(days=1),
    timeout=900,
)
def legal_hold_destruction_sweep():
    """Daily: destroy vaulted legal-hold content whose one-year
    preservation period has run (see sweep_legal_hold_destructions).
    Holds without a CyberTipline confirmation date, and holds
    flagged for law enforcement, are never touched."""
    destroyed = sweep_legal_hold_destructions()
    print(f"legal hold destruction sweep: {len(destroyed)} destroyed")
    return destroyed


def _short_word_check(job: dict, out_path: Path):
    """The word check stage for a finished short: the same stage
    the generation finishing chain runs (see _word_check_for_job
    inside api()), duplicated at top level the way the clip
    helpers mirror their api() counterparts. The delivered audio
    is transcribed and aligned against the spoken script, and a
    same-voice repair is spliced in when the audio app returns
    one. The short was voiced by the platform's own Kokoro
    stage, so the fix pass is always eligible. Outcomes land on
    the job record in the same fields; a stage failure flags
    "unavailable" and never blocks the delivery."""
    script = (job.get("speech_script") or "").strip()
    if not script or job.get("word_check_status"):
        return
    files_dir = Path("/data/files")
    audio_path = files_dir / f"{job['id']}.wordcheck.wav"
    fixed_path = files_dir / f"{job['id']}.wordfix.wav"
    swapped_path = files_dir / f"{job['id']}.wordfix.mp4"
    try:
        proc = subprocess.run(
            ["ffmpeg", "-y", "-i", str(out_path), "-vn",
             "-acodec", "pcm_s16le", str(audio_path)],
            capture_output=True, text=True, timeout=600)
        if proc.returncode != 0 or not audio_path.exists():
            raise RuntimeError("final audio extraction failed")
        voice = ""
        if job.get("voiceover_status") == "ready" \
                and job.get("speech_voice") != CLONE_VOICE_ID:
            voice = job.get("speech_voice") or DEFAULT_SPEECH_VOICE
        word_check = modal.Function.from_name(
            "sinclip-audio", "word_check")
        result = word_check.remote(
            audio_path.read_bytes(), script, voice)
        fixed = result.pop("audio", None)
        if fixed:
            fixed_path.write_bytes(fixed)
            proc = subprocess.run(
                ["ffmpeg", "-y", "-i", str(out_path),
                 "-i", str(fixed_path),
                 "-map", "0:v:0", "-map", "1:a:0",
                 "-c:v", "copy", "-c:a", "aac", "-b:a", "160k",
                 "-shortest", str(swapped_path)],
                capture_output=True, text=True, timeout=1800)
            if proc.returncode != 0 or not swapped_path.exists():
                raise RuntimeError("fixed audio swap failed")
            swapped_path.replace(out_path)
        job["word_check_status"] = result.get("status") \
            or "unavailable"
        job["word_check_listen_at"] = \
            result.get("listen_at") or []
        job["word_check_wrong"] = result.get("wrong") or []
        jobs[job["id"]] = job
    except Exception:
        job["word_check_status"] = "unavailable"
        jobs[job["id"]] = job
    finally:
        for path in (audio_path, fixed_path, swapped_path):
            try:
                path.unlink(missing_ok=True)
            except Exception:
                pass


# The AI pictures wait inside one short: the house image lane
# renders on the Kaggle ComfyUI worker, whose cold start (a
# session boot, the ComfyUI setup, the model staging) takes
# minutes on a cold day and seconds on a warm one. The wait is
# bounded well inside the runner's own hour, and a short whose
# pictures do not land inside it falls back to stock footage
# rather than dying on a worker it does not control.
SHORTS_AI_WAIT_SECONDS = 1500


def _short_ai_scenes(job: dict, lines: list):
    """Queue one house image job per script line on the Kaggle
    ComfyUI worker and wait for the stills: the AI visuals mode
    of the shorts lane. The children are ordinary house image
    job records (kind image, the kaggle-comfy route) carrying
    no charge and no quota of their own: the short itself
    already took the lane's quota at creation, the pictures are
    its scenes, and the compute is the free Kaggle quota the
    house image lane already runs on. A short_parent mark keeps
    them out of the library and the gallery. Returns the still
    paths in line order, or None when any picture fails or the
    wait runs out; children still unfinished at that point are
    closed on the spot so a kernel never renders a picture
    nobody is waiting for."""
    prompts = shorts.image_prompts_for_lines(
        lines, job.get("short_style") or shorts.VISUAL_STYLE_DEFAULT)
    base_seed = int(hashlib.sha256(
        job["id"].encode()).hexdigest()[:8], 16) % 90000 + 10000
    children = []
    for i, prompt in enumerate(prompts):
        child = {
            "id": pysecrets.token_hex(8),
            "user_id": job["user_id"],
            "worker_job_id": None,
            "provider": "kaggle-comfy",
            "route": "kaggle",
            "kind": "image",
            "lane": "image",
            "model": None,
            "prompt": prompt,
            "seed": base_seed + i,
            "user_prompt": prompt,
            "camera_presets": [],
            "camera_preset_names": [],
            "camera_look": {},
            "status": "queued",
            "error": None,
            "bytes": None,
            "created_at": _now(),
            "created_ip": job.get("created_ip"),
            "charged_cents": 0,
            "free_tier": False,
            "included_cost_cents": 0,
            "cost_cents": 0.0,
            "music_prompt": None,
            "plan_at_job": job.get("plan_at_job"),
            "retry_of": None,
            "last_poll": 0,
            "aspect_ratio": "9:16",
            "short_parent": job["id"],
        }
        jobs[child["id"]] = child
        _index_job(child)
        children.append(child["id"])
    _wake_comfy_kernel()
    deadline = time.time() + SHORTS_AI_WAIT_SECONDS
    paths = None
    while time.time() < deadline:
        states = [(jobs.get(cid) or {}) for cid in children]
        if all(s.get("status") == "done" for s in states):
            try:
                data_volume.reload()
            except Exception:
                pass
            found = [FILES_DIR / f"{cid}.png" for cid in children]
            if all(p.exists() for p in found):
                paths = found
            break
        if any(s.get("status") == "error" for s in states):
            break
        time.sleep(10)
    if paths is None:
        for cid in children:
            rec = jobs.get(cid) or {}
            if rec.get("status") in ("queued", "running"):
                rec["status"] = "error"
                rec["error"] = (
                    "the short moved on without this picture")
                rec["internal_error"] = (
                    "the shorts AI pictures wait ended first")
                jobs[cid] = rec
        return None
    job["short_picture_jobs"] = children
    job["short_picture_prompts"] = prompts
    return paths


def _clone_debit_once(parent: dict) -> bool:
    """Take the one-time voice cloning charge for a parent job
    (pricing.voice_clone_price_cents: the nominal basis marked
    up once, 2 cents; the owner pays the Kaggle route's true
    raw cost, $0, so his stamp is 0 and nothing moves). Runs
    at module level because the shorts processor, which runs
    outside the web layer, debits through the same path; the
    users Dict write mirrors save_user exactly. Idempotent
    through the parent record's clone_charged stamp. Returns
    False only when a paying account's balance cannot cover
    the charge, so the caller fails the voice stage clean
    instead of cloning on credit."""
    if parent.get("clone_charged"):
        return True
    user = users.get(f"id:{parent['user_id']}")
    if not user:
        return False
    price = pricing.voice_clone_price_cents(
        owner=bool(user.get("is_owner")))
    if price:
        if int(user.get("balance_cents", 0)) < price:
            return False
        user["balance_cents"] = int(user.get("balance_cents", 0)) - price
        users[f"id:{user['id']}"] = user
        users[f"email:{user['email']}"] = user
    parent["clone_charge_cents"] = price
    parent["clone_charged"] = True
    jobs[parent["id"]] = parent
    return True


def _clone_refund_if_unsuccessful(parent_id: str) -> None:
    """Give the cloning charge back when no clone child of the
    parent ever succeeded: the platform never keeps money for
    a cloned voice it did not deliver. Idempotent through the
    parent record's clone_charge_refunded stamp; called from
    the wait helper when its wait ends empty and from the
    worker fail endpoint when a child fails."""
    parent = jobs.get(parent_id) or {}
    charge = int(parent.get("clone_charge_cents") or 0)
    if not charge or parent.get("clone_charge_refunded"):
        return
    children = [jobs.get(cid) or {}
                for cid in parent.get("clone_children") or []]
    if any(c.get("status") == "done" for c in children):
        return
    user = users.get(f"id:{parent['user_id']}")
    if user:
        user["balance_cents"] = int(user.get("balance_cents", 0)) + charge
        users[f"id:{user['id']}"] = user
        users[f"email:{user['email']}"] = user
    if parent.get("clone_folded_cents"):
        # Folded jobs (Jack, 2026-11-23) took the clone price
        # inside the creation charge, so the refunded amount
        # comes back out of the record's charged figure too:
        # a later full restore of that figure then returns
        # exactly what is still held, never the clone price
        # a second time.
        parent["charged_cents"] = max(
            0, int(parent.get("charged_cents") or 0) - charge)
    parent["clone_charge_refunded"] = True
    jobs[parent_id] = parent


def _queue_clone_child(parent: dict, text: str) -> str:
    """Queue one voice_clone child job for the Kaggle voice
    worker: the text to speak, the parent's reference clip
    (served to the worker through the worker endpoints), and
    the optional transcript of that clip. The child carries
    no charge of its own; the parent took the one-time clone
    charge. A clone_parent mark keeps the child out of the
    library and the gallery."""
    child = {
        "id": pysecrets.token_hex(8),
        "user_id": parent["user_id"],
        "worker_job_id": None,
        "provider": "kaggle-voice",
        "kind": "voice_clone",
        "status": "queued",
        "error": None,
        "bytes": None,
        "created_at": _now(),
        "created_ip": parent.get("created_ip"),
        "charged_cents": 0,
        "clone_parent": parent["id"],
        "clone_text": text,
        "clone_reference_text":
            parent.get("clone_reference_text") or "",
        "clone_reference_ext":
            parent.get("clone_reference_ext") or "wav",
        "plan_at_job": parent.get("plan_at_job"),
    }
    jobs[child["id"]] = child
    _index_job(child)
    parent.setdefault("clone_children", []).append(child["id"])
    jobs[parent["id"]] = parent
    return child["id"]


def _wait_clone_child(parent: dict, text: str,
                      wait_seconds=None):
    """Clone the parent job's reference voice speaking one
    text on the Kaggle voice worker and wait for the wav: the
    voice cloning twin of _short_ai_scenes. Debits the
    parent's one-time clone charge first (a balance that
    cannot cover it ends the wait before anything queues),
    queues one child, wakes the voice kernel, and polls the
    child record. Returns the finished wav path, or None when
    the child fails or the wait runs out; a child still open
    at that point is closed on the spot so a kernel never
    clones for nobody, and the charge goes back whenever no
    child of the parent ever succeeded."""
    if wait_seconds is None:
        wait_seconds = CLONE_WAIT_SECONDS
    if not _clone_debit_once(parent):
        return None
    # Rejoin before queueing: a caller that was cut off
    # mid-wait (the video voiceover stage waits inside the
    # web function) leaves its child cooking, and the next
    # caller for the same words waits on that same child
    # instead of paying a second synthesis for them. A child
    # already done hands its file straight back.
    child_id = None
    for cid in parent.get("clone_children") or []:
        rec = jobs.get(cid) or {}
        if rec.get("clone_text") != text:
            continue
        if rec.get("status") == "done":
            try:
                data_volume.reload()
            except Exception:
                pass
            done_path = FILES_DIR / "voice_clone" / f"{cid}.wav"
            if done_path.exists():
                return done_path
        if rec.get("status") in ("queued", "running"):
            child_id = cid
            break
    if child_id is None:
        child_id = _queue_clone_child(parent, text)
    _wake_voice_kernel()
    deadline = time.time() + wait_seconds
    while time.time() < deadline:
        rec = jobs.get(child_id) or {}
        if rec.get("status") == "done":
            try:
                data_volume.reload()
            except Exception:
                pass
            path = FILES_DIR / "voice_clone" / f"{child_id}.wav"
            return path if path.exists() else None
        if rec.get("status") == "error":
            break
        time.sleep(10)
    rec = jobs.get(child_id) or {}
    if rec.get("status") in ("queued", "running"):
        rec["status"] = "error"
        rec["error"] = "the voice wait ended first"
        rec["internal_error"] = "the clone wait ended first"
        jobs[child_id] = rec
    _clone_refund_if_unsuccessful(parent["id"])
    return None


def _short_custom_bed_for_job(job: dict):
    """The custom music bed for one short, made from the
    user's own description on the job record. The _bed_for_job
    pattern, per job: the ACE-Step bed stage reads the
    description with the instrumental close appended, the bed
    is cached per job on the data Volume, and any audio stage
    failure falls back to the house bed and flags the job
    record, so delivery never breaks on the music stage."""
    prompt = (job.get("music_prompt") or "").strip()
    if not prompt:
        return BED_PATH if BED_PATH.exists() else None
    bed_file = FILES_DIR / "beds" / f"{job['id']}.wav"
    if bed_file.exists():
        return bed_file
    try:
        payload = _bed_payload_for_job(job)
        data = _audio_bytes("bed", payload, job, BED_WAIT_SECONDS)
        bed_file.parent.mkdir(parents=True, exist_ok=True)
        bed_file.write_bytes(data)
        data_volume.commit()
        return bed_file
    except Exception:
        job["music_fallback"] = True
        jobs[job["id"]] = job
        return BED_PATH if BED_PATH.exists() else None


def _short_bed_for_job(job: dict):
    """The music bed one short runs under, by the job's picked
    style. House is the platform bed file. A named style rides
    the platform's ACE-Step bed stage with its fixed caption,
    the _bed_for_job pattern, but cached by style on the data
    Volume so each style is generated once and then shared.
    The custom pick rides the same stage per job, from the
    user's own description on the job record. No music
    returns None. Any audio stage failure falls back to the
    house bed and flags the job record, so delivery never
    breaks on the music stage."""
    style = job.get("short_music") or "none"
    if style == "none":
        return None
    if style == SHORTS_CUSTOM_MUSIC:
        return _short_custom_bed_for_job(job)
    caption = (SHORTS_MUSIC_STYLES.get(style) or {}).get(
        "caption") or ""
    if not caption:
        return BED_PATH if BED_PATH.exists() else None
    bed_file = FILES_DIR / "beds" / f"shorts_{style}.wav"
    if bed_file.exists():
        return bed_file
    try:
        data = _audio_bytes(
            "bed",
            {"caption": f"{caption}, instrumental, no vocals",
             "seed": 7},
            job, BED_WAIT_SECONDS)
        bed_file.parent.mkdir(parents=True, exist_ok=True)
        bed_file.write_bytes(data)
        data_volume.commit()
        return bed_file
    except Exception:
        job["music_fallback"] = True
        jobs[job["id"]] = job
        return BED_PATH if BED_PATH.exists() else None


@app.function(
    image=clip_image,
    secrets=[
        modal.Secret.from_name("moonfactory-providers"),
        modal.Secret.from_name("moonfactory-secrets"),
        modal.Secret.from_name("moonfactory-kaggle"),
    ],
    volumes={"/data": data_volume, "/worker-models": worker_models},
    cpu=4.0,
    memory=8192,
    timeout=3600,
    scaledown_window=60,
)
def process_short_job(job_id: str):
    """Run one faceless short end to end on CPU: one scene per
    script line (a stock clip, or an AI picture in one picked
    style, animated with a slow zoom or pan), Kokoro narration
    per line through the platform's own audio stage, captions
    timed from the measured narration lengths, the picked music
    bed underneath, and one ffmpeg assembly. Shorts land in the
    library as first-class
    jobs (lane "shorts") with the finished file already in
    place, the way clip jobs do, so the file, gallery, poster
    and delete routes serve them unchanged. The lane is free:
    there is no hold, and a failure charges nothing."""
    job = jobs.get(job_id)
    if not job:
        return
    # A warm container's Volume view can predate the job's
    # creation; reload before touching any file.
    try:
        data_volume.reload()
    except Exception:
        pass
    files_dir = Path("/data/files")
    files_dir.mkdir(parents=True, exist_ok=True)
    work = Path("/data/shorts-work") / job_id
    work.mkdir(parents=True, exist_ok=True)

    def set_stage(stage, status="running"):
        job["stage"] = stage
        job["status"] = status
        jobs[job_id] = job

    try:
        lines = list(job.get("short_lines") or [])
        if not lines:
            raise RuntimeError("the job carries no script lines")
        # Queue the music bed now, before the scene and
        # narration stages, so a cold Kaggle audio session
        # warms up while the rest of the short is made; the
        # bed helper rejoins this same child at assembly.
        _queue_short_bed_child(job)
        voice = job.get("speech_voice") or DEFAULT_SPEECH_VOICE
        stock_key = shorts._env_value("PEXELS_API_KEY")

        image_paths = None
        if (job.get("short_visuals") or "stock") in ("ai", "overlay"):
            set_stage("Making the pictures")
            image_paths = _short_ai_scenes(job, lines)
            if image_paths is None:
                # The pictures could not be made inside the
                # wait: the short falls back to stock footage
                # and the record says so, the same flagged
                # fallback shape the audio stages use, rather
                # than dying on a worker it does not control.
                job["short_visuals_used"] = "stock"
                job["visuals_fallback"] = True
                jobs[job_id] = job
            else:
                job["short_visuals_used"] = "ai"
                job["short_scenes"] = [
                    {"provider": "house-image",
                     "terms": prompt,
                     "page_url": "", "credit": "", "license": ""}
                    for prompt in job.get("short_picture_prompts")
                    or []]
                jobs[job_id] = job
        scenes = []
        if image_paths is None:
            set_stage(SHORTS_STAGES[0])
            for i, line in enumerate(lines):
                terms = shorts.search_terms_for_line(
                    line, job.get("short_topic") or "")
                scenes.append(shorts.find_stock_clip(
                    terms, work / "stock", i, stock_key))
            job["short_scenes"] = [
                {key: scene.get(key) for key in (
                    "provider", "terms", "page_url", "credit",
                    "license")}
                for scene in scenes
            ]
            jobs[job_id] = job

        overlay_clips = None
        if (job.get("short_visuals") or "") == "overlay":
            # B-roll overlays (2026-11-23, the motion b-roll
            # playbook): one stock clip per line, fetched the
            # same way the stock scenes are, laid over the main
            # picture in a corner panel timed to the line's
            # narration in the assembly. The base picture is
            # the AI pictures lane above (with its own stock
            # fallback). A line whose search comes back empty
            # simply gets no panel; the short never dies on
            # an overlay.
            set_stage("Finding the B-roll")
            overlay_clips = []
            broll_records = []
            for i, line in enumerate(lines):
                terms = shorts.search_terms_for_line(
                    line, job.get("short_topic") or "")
                try:
                    clip = shorts.find_stock_clip(
                        terms, work / "broll", i, stock_key)
                except Exception:
                    clip = None
                overlay_clips.append(clip)
                if clip is not None:
                    broll_records.append(
                        {"provider": clip.get("provider"),
                         "terms": clip.get("terms"),
                         "page_url": clip.get("page_url"),
                         "credit": clip.get("credit"),
                         "license": clip.get("license")})
            job["short_broll"] = broll_records
            job["short_visuals_used"] = (
                "overlay-ai" if image_paths is not None
                else "overlay-stock")
            jobs[job_id] = job

        set_stage(SHORTS_STAGES[1])
        line_wavs = []
        line_durations = []
        for i, line in enumerate(lines):
            wav = work / f"line_{i}.wav"
            if voice == CLONE_VOICE_ID:
                # Voice cloning (2026-11-21): the line is spoken
                # by the cloned voice from the Kaggle voice
                # worker, never by a Kokoro voice standing in
                # for it. A clone that cannot be made fails the
                # short clean, the same shape as a voice failure
                # below; the wait helper has already returned
                # the one-time clone charge if no line of this
                # short was ever cloned.
                cloned = _wait_clone_child(
                    job, line,
                    wait_seconds=CLONE_WAIT_SHORTS_SECONDS)
                if cloned is None:
                    raise RuntimeError(
                        "the cloned voice could not be made")
                shutil.copyfile(cloned, wav)
            else:
                data = _audio_bytes(
                    "voiceover", {"text": line, "voice": voice},
                    job, VOICE_WAIT_SECONDS)
                wav.write_bytes(data)
            duration = shorts.probe(wav)["duration"]
            if duration <= 0:
                raise RuntimeError("the narration came back empty")
            line_wavs.append(wav)
            line_durations.append(duration)
        job["voiceover_status"] = "ready"
        jobs[job_id] = job
        scene_durations = []
        for i, duration in enumerate(line_durations):
            pad = shorts.TAIL_SECONDS if i == len(line_durations) - 1 \
                else shorts.LINE_GAP_SECONDS
            scene_durations.append(duration + pad)
        if job.get("short_beat_sync"):
            # Beat synced cuts (2026-11-23, the beat sync
            # playbook): every scene runs on to the next beat
            # of the picked music's tempo, so the picture cuts
            # land on the beat. The narration track is built
            # against the same lengths below, so the voice
            # pads out and stays locked to the picture.
            bpm = (SHORTS_MUSIC_STYLES.get(
                job.get("short_music") or "none") or {}).get(
                    "bpm") or 100
            scene_durations = shorts.snap_durations_to_beat(
                scene_durations, bpm)
            job["short_beat_bpm"] = bpm
            jobs[job_id] = job
        narration = shorts.build_narration_track(
            line_wavs, line_durations, work,
            scene_durations=scene_durations)
        timings = []
        cursor = 0.0
        for i, duration in enumerate(line_durations):
            timings.append((cursor, duration))
            cursor += scene_durations[i]

        set_stage(SHORTS_STAGES[2])
        # The No captions pick (Jack, 2026-11-20): no captions
        # file is written and the assembly runs with no
        # subtitles filter, so the finished short carries no
        # captions at all. (The opening title overlay left
        # shorts entirely, Jack 2026-11-24; a lower third
        # stored on an older job record is simply never read.)
        ass_path = None
        caption_style = job.get("short_caption_style") \
            or shorts.CAPTION_STYLE_DEFAULT
        if caption_style != "none":
            ass_path = work / "captions.ass"
            ass_path.write_text(
                shorts.build_captions_ass(
                    lines, timings,
                    style=caption_style),
                encoding="utf-8")

        set_stage(SHORTS_STAGES[3])
        if image_paths is not None:
            scene_paths = []
            for i, (still, duration) in enumerate(
                    zip(image_paths, scene_durations)):
                scene_file = work / f"ai_scene_{i}.mp4"
                shorts.animate_image_scene(
                    still, duration, scene_file, i)
                scene_paths.append(scene_file)
        else:
            scene_paths = [Path(scene["path"]) for scene in scenes]
        overlay_specs = None
        if overlay_clips is not None:
            overlay_specs = []
            for i, clip in enumerate(overlay_clips):
                if clip is None:
                    overlay_specs.append(None)
                else:
                    overlay_specs.append({
                        "path": clip["path"],
                        "start": timings[i][0],
                        "duration": scene_durations[i],
                    })
        out_path = files_dir / f"{job_id}.mp4"
        info = shorts.assemble_short(
            scene_paths,
            scene_durations, narration, ass_path, out_path, work,
            bed_path=_short_bed_for_job(job),
            watermark=bool(job.get("free_tier")),
            font_path=FONT_PATH,
            overlays=overlay_specs)
        job["duration_seconds"] = round(float(info["duration"]), 2)
        job["bytes"] = out_path.stat().st_size
        jobs[job_id] = job
        # The word check runs on the delivered file here (the
        # processor is the finishing chain for this lane), then
        # the poster is cut from the final file.
        _short_word_check(job, out_path)
        # The word check may have swapped the delivered file
        # (its repair splice), so the content fingerprint is
        # taken only now, over the final bytes.
        stamp_content_hash(job, out_path)
        classify_job_output(job, out_path)
        try:
            subprocess.run(
                ["ffmpeg", "-y", "-ss", "0.5", "-i", str(out_path),
                 "-vframes", "1", "-q:v", "3",
                 str(files_dir / f"{job_id}.jpg")],
                capture_output=True, timeout=120)
        except Exception:
            pass
        job["stage"] = "Done"
        job["status"] = "done"
        jobs[job_id] = job
        data_volume.commit()
    except Exception as exc:  # noqa: BLE001
        job["status"] = "error"
        job["error"] = "the short could not be made, nothing was charged"
        job["internal_error"] = str(exc)[:300]
        job["stage"] = None
        if job.get("voiceover_status") != "ready":
            job["voiceover_status"] = "unavailable"
        jobs[job_id] = job
        # A folded clone charge (taken at creation, Jack
        # 2026-11-23) goes back whenever no line of this
        # short was ever cloned, so a failure before or at
        # the narration stage charges nothing, as the error
        # above says. The helper re-reads the record saved
        # just above, so it runs after that save. Idempotent,
        # and a no-op when a clone child did succeed.
        _clone_refund_if_unsuccessful(job_id)
        data_volume.commit()


