ILLEGAL_ACT_PHRASES = (
    "having sex", "have sex", "has sex", "oral sex",
    "anal sex", "sex with", "sexual intercourse",
)

ILLEGAL_FAMILY_TERMS = frozenset({
    "mother", "father", "sister", "brother", "mom", "dad",
    "daughter", "son", "stepmother", "stepfather",
    "stepsister", "stepbrother", "stepmom", "stepdad",
    "stepson", "stepdaughter", "aunt", "uncle",
})

ILLEGAL_HELPLESS_TERMS = frozenset({
    "unconscious", "drugged", "asleep", "sleeping",
    "sedated", "intoxicated", "blackout", "comatose",
})

ILLEGAL_HELPLESS_PHRASES = ("passed out",)

# Real-person signals: a deepfake term, or a proper-name
# pattern next to a sexual signal. The name heuristic is
# pragmatic, not certain: it reads two or more consecutive
# capitalized words (or an all-caps pair) in the user's raw
# text, skips the ones a place preposition introduces (a
# nude beach in New York is a place, not a person) and a
# small exclusion shelf of places, brands, and stock
# phrases. It cannot see single names, stage names, or
# misspellings, and a fictional character's full name reads
# as a name: both limits are accepted with the method.
ILLEGAL_DEEPFAKE_TERMS = frozenset({
    "deepfake", "deepfakes", "deepfaked", "nudify",
    "nudifier", "faceswap", "faceswapped",
})

ILLEGAL_DEEPFAKE_PHRASES = ("deep fake", "face swap")

ILLEGAL_PERSON_CONTEXT = frozenset({
    "celebrity", "celebrities", "famous", "actress", "actor",
    "singer", "influencer", "president", "politician",
})

_NAME_PAIR_RE = re.compile(
    r"[A-Z][a-z]+(?:['\u2019][a-z]+)?"
    r"(?:\s+[A-Z][a-z]+(?:['\u2019][a-z]+)?)+")
_NAME_CAPS_RE = re.compile(r"[A-Z]{2,}(?:\s+[A-Z]{2,})+")
_PLACE_LEADERS = frozenset({
    "in", "at", "to", "from", "near", "over", "across",
    "into", "toward", "towards", "inside", "outside",
})
_NAME_DETERMINERS = frozenset({
    "the", "a", "an", "this", "that", "my", "his", "her",
    "their", "our", "your", "it", "on", "at", "but", "and",
    "for", "with",
})
_NAME_EXCLUSIONS = frozenset({
    "victoria secret", "victorias secret", "adults only",
    "high definition", "ultra high", "new york",
    "new york city", "los angeles", "las vegas",
    "san francisco", "san diego", "hong kong", "south korea",
    "north korea", "united states", "united kingdom",
    "great britain", "new zealand", "south africa",
    "saudi arabia", "sri lanka", "costa rica", "puerto rico",
    "dominican republic", "czech republic", "ivory coast",
    "sierra leone", "burkina faso", "el salvador",
    "san marino", "vatican city", "kuala lumpur",
    "buenos aires", "rio de janeiro", "sao paulo",
    "cape town", "tel aviv", "abu dhabi", "new delhi",
})
_CAPS_STOPWORDS = frozenset({
    "THE", "AND", "NOT", "FOR", "YOU", "ARE", "BUT", "ALL",
    "ANY", "NEW", "HER", "HIS", "ITS", "OUR", "OUT", "WHO",
    "WHY", "HOW", "NOW", "ONE", "TWO", "SHE", "HIM", "WAS",
    "GET", "LET", "SAY", "SEE", "TOO", "USE", "WAY", "DAY",
})


def _prompt_names_person(raw: str) -> bool:
    """Whether the raw prompt text carries a proper-name
    pattern: two or more consecutive capitalized words, or
    an all-caps pair, that is not a place phrase or a stock
    phrase from the exclusion shelf."""
    for rx in (_NAME_PAIR_RE, _NAME_CAPS_RE):
        for match in rx.finditer(raw):
            words = match.group(0).split()
            if rx is _NAME_PAIR_RE and len(words) > 1 \
                    and words[0].lower() in _NAME_DETERMINERS:
                words = words[1:]
            if len(words) < 2:
                continue
            if rx is _NAME_CAPS_RE and any(
                    w in _CAPS_STOPWORDS for w in words):
                continue
            lowered = [w.lower().strip("'\u2019") for w in words]
            windows = [" ".join(lowered[i:i + n])
                       for n in (2, 3)
                       for i in range(len(lowered) - n + 1)]
            if any(w in _NAME_EXCLUSIONS for w in windows):
                continue
            before = re.findall(r"[A-Za-z]+", raw[:match.start()])
            if before and before[-1].lower() in _PLACE_LEADERS:
                continue
            return True
    return False


def _prompt_states_minor_age(lowered: str, padded: str) -> bool:
    """Whether the text states an age under 18 in words:
    digits (15 year old, 15 y/o) or spelled out (fifteen
    years old). The digit pattern reads the plain lowered
    text, never the leet decode: the decode map turns 1
    into i and 5 into s, which would erase every age."""
    if _AGE_NUMBER_RE.search(lowered):
        return True
    return any(f" {w} year old " in padded
               or f" {w} years old " in padded
               for w in _SPELLED_AGES)


def prompt_is_illegal(text):
    """The category of illegal content a user's own prompt
    asks for, or None: "hard" (sexual content involving
    minors), "sexual-violence" (rape, non-consent, incest,
    bestiality, snuff), or "real-person" (sexual content
    naming a real person, NCII and deepfakes). Deterministic,
    no calls out. Lawful adult content returns None: this
    gate is not the gallery scan, and an explicit adult
    prompt passes it exactly as before."""
    if not text:
        return None
    raw = str(text)
    decoded = raw.lower().translate(_PROMPT_LEET)
    tokens = re.findall(r"[a-z0-9]+", decoded)
    token_set = set(tokens)
    padded = " " + " ".join(tokens) + " "
    squeezed = "".join(tokens)

    def has_phrase(phrases):
        return any(" " + p + " " in padded for p in phrases)

    # Hard, standalone: the words are the violation by
    # themselves, whatever surrounds them.
    if token_set & ILLEGAL_HARD_TERMS:
        return "hard"
    if has_phrase(ILLEGAL_HARD_PHRASES):
        return "hard"
    if any(t in squeezed for t in ILLEGAL_HARD_SQUEEZED):
        return "hard"
    sexual = prompt_is_nsfw(raw)
    act = bool(token_set & ILLEGAL_ACT_TERMS) \
        or has_phrase(ILLEGAL_ACT_PHRASES)
    edu_shield = bool(token_set & ILLEGAL_EDUCATION_TERMS) \
        and not act
    minor = bool(token_set & ILLEGAL_MINOR_TERMS) \
        or has_phrase(ILLEGAL_MINOR_PHRASES)
    if minor and sexual and not edu_shield:
        return "hard"
    if sexual and not edu_shield \
            and _prompt_states_minor_age(raw.lower(), padded):
        return "hard"
    # "Aged up" evasions: aging a minor subject up on paper
    # is the same request with a fig leaf, sexual or not.
    if minor and (" aged up " in padded or "agedup" in squeezed
                  or " all grown up " in padded):
        return "hard"
    # Sexual violence and non-consent.
    if token_set & ILLEGAL_VIOLENCE_TERMS:
        return "sexual-violence"
    if has_phrase(ILLEGAL_VIOLENCE_PHRASES):
        return "sexual-violence"
    if act and token_set & ILLEGAL_FAMILY_TERMS:
        return "sexual-violence"
    helpless = bool(token_set & ILLEGAL_HELPLESS_TERMS) \
        or has_phrase(ILLEGAL_HELPLESS_PHRASES)
    if act and helpless:
        return "sexual-violence"
    # Real-person sexual content (NCII, deepfakes).
    deepfake = bool(token_set & ILLEGAL_DEEPFAKE_TERMS) \
        or has_phrase(ILLEGAL_DEEPFAKE_PHRASES)
    named = _prompt_names_person(raw)
    if sexual and named:
        return "real-person"
    if deepfake and (sexual or named
                     or token_set & ILLEGAL_PERSON_CONTEXT):
        return "real-person"
    return None


def record_illegal_refusal(user, lane, category, prompt_text,
                           ip) -> bool:
    """Write one illegal-gate refusal record and run the
    enforcement ladder. The record is server-side only (the
    moonfactory-refusals Dict): account id, timestamp, lane,
    category, the prompt as typed, and the creating IP; it is
    never exposed in any user-facing or public payload. The
    ladder: a hard refusal suspends the account on the spot;
    any other category suspends at the third refusal on the
    account. Suspension is a flag on the user record that the
    creation gate checks before anything else, so a suspended
    account creates nothing on any path. Returns whether the
    account is suspended after this refusal. Never raises:
    the refusal itself is the caller's raise, and a storage
    failure must not turn it into a 500."""
    try:
        rec = {
            "id": pysecrets.token_hex(8),
            "user_id": user.get("id"),
            "created_at": _now(),
            "lane": lane,
            "category": category,
            "prompt": prompt_text,
            "created_ip": ip or None,
        }
        refusals[rec["id"]] = rec
        count = int(user.get("illegal_refusals") or 0) + 1
        user["illegal_refusals"] = count
        if category == "hard" or count >= ILLEGAL_SUSPEND_AFTER:
            user["suspended"] = True
            user["suspended_at"] = _now()
            user["suspended_reason"] = "illegal content gate"
        users[f"id:{user['id']}"] = user
        if user.get("email"):
            users[f"email:{user['email']}"] = user
        return bool(user.get("suspended"))
    except Exception as exc:  # noqa: BLE001
        print(f"illegal refusal record failed: {exc}")
        return bool(user.get("suspended"))


def job_is_uncensored(job: dict) -> bool:
    """Whether a job ran on an uncensored lane or build: the
    house NSFW lane, one of the uncensored catalog video models
    (the same UNCENSORED_VIDEO_MODELS flag /api/config serves
    and the studio picker renders as the Uncensored marker, the
    house Wan 2.2 included: open weights on our own worker, no
    provider moderation layer), or an image lane whose pricing
    entry carries the uncensored flag (Krea 2 Verite, the
    Z-Image uncensored builds, and their shelf kin). This is
    the SCOPE of the prompt judging, not a verdict: since
    2026-11-23 an in-scope job is NSFW for gallery purposes
    only when its own prompt scans NSFW (job_is_nsfw)."""
    if not job:
        return False
    if job.get("lane") == "nsfw":
        return True
    model = job.get("model")
    if not model and job.get("lane") in pricing.MEASURED_COST_CENTS:
        # Legacy house records predate the model field. A job on
        # a house lane with no model recorded ran the default
        # house model, the same fallback public_job renders, so
        # classify it by that model instead of letting the
        # missing field slip it past the gallery rule (found by
        # the 2026-11-18 verification bundle: two Nov 16 balloon
        # clips with no model field were still listed).
        model = DEFAULT_MODEL
    if model in UNCENSORED_VIDEO_MODELS:
        return True
    image_lane = pricing.IMAGE_LANES.get(
        job.get("image_model") or "") or {}
    return bool(image_lane.get("uncensored"))


# ---------------------------------------------------------------------------
# The 18+ gate (Jack, 2026-11-24): the uncensored scope, the
# same job_is_uncensored definition the upload scanning uses,
# is adults only. The first time an account creates in that
# scope it confirms once, in place at the Generate moment;
# the confirmation stamps the account and is never asked
# again. Regular lanes never see any of this. The server
# refuses an unstamped account on an in-scope creation
# before any quote, hold, charge, free count, or dispatch,
# so a client that skips the in-place confirmation still
# creates nothing.
# ---------------------------------------------------------------------------

ADULT_CONFIRMATION_REQUIRED = (
    "Confirm you are 18 years old or older before using this model.")


def adult_gate_refusal(user, probe):
    """The refusal message for an in-scope creation by an
    account without the 18+ stamp, or None when the creation
    proceeds: out of scope, or already confirmed. `probe` is
    any dict job_is_uncensored reads, the same model and lane
    pair the upload scanning judges at creation."""
    if not job_is_uncensored(probe):
        return None
    if (user or {}).get("adult_confirmed_at"):
        return None
    return ADULT_CONFIRMATION_REQUIRED


def stamp_adult_confirmation(user):
    """Write the one time 18+ stamp on an account. The stamp
    is written once: an account that already carries it keeps
    its original time, and this returns False."""
    if user.get("adult_confirmed_at"):
        return False
    user["adult_confirmed_at"] = _now()
    return True


def job_has_image_input(job: dict) -> bool:
    """Whether the job took an uploaded image as an input: a
    start or end frame, reference images, or an edit source.
    Read off the job record's own stored fields, so it is
    computed live at read time like the rest of the gallery
    classification:
    - has_start_image / has_source_image: the booleans stored
      at creation on the records that do not keep the image
      itself (per-second API jobs, image jobs).
    - start_image_png_b64 / end_image_png_b64: the house
      record stores the frames themselves.
    - reference_image_urls: stored on per-second API records.
    - Two shapes are definitional, so legacy records carry the
      fact in their model or lane alone: a model on
      START_IMAGE_REQUIRED_MODELS could not have been created
      without a start image (create refuses it), and an image
      lane whose pricing entry is an edit lane takes a source
      image on every job it runs."""
    if not job:
        return False
    if job.get("has_start_image") or job.get("has_source_image"):
        return True
    if job.get("start_image_png_b64") or job.get("end_image_png_b64"):
        return True
    if job.get("reference_image_urls"):
        return True
    if job.get("model") in START_IMAGE_REQUIRED_MODELS:
        return True
    image_lane = pricing.IMAGE_LANES.get(
        job.get("image_model") or "") or {}
    return bool(image_lane.get("edit"))


def job_is_nsfw(job: dict) -> bool:
    """Whether a job is NSFW for public gallery purposes (Jack,
    2026-11-18; prompt-judged 2026-11-23): the job ran on an
    uncensored lane or build (job_is_uncensored) AND either the
    user's own prompt for it scans NSFW (prompt_is_nsfw) or it
    took an uploaded image as an input (job_has_image_input).
    The lane alone no longer classifies: not every uncensored
    generation is NSFW, so a clean text-only generation is
    gallery-eligible exactly like a regular generation. The
    image bar is Jack's refinement later the same day: the
    prompt scan reads words, not pictures, so an uncensored
    generation built on an uploaded image can never be judged
    clean from its prompt, however tame the words read; it
    never lists. The scan reads the record's user_prompt (the
    words the user typed, kept apart from any server
    composition), falling back to prompt on records that
    predate the field. Computed live at read time, so jobs
    finished under the old blanket lane rule are rejudged by
    their stored prompts and stored image inputs."""
    if not job_is_uncensored(job):
        return False
    if job_has_image_input(job):
        return True
    return prompt_is_nsfw(
        job.get("user_prompt") or job.get("prompt") or "")


# Picker classes (Jack, 2026-11-19; group labels restyled
# 2026-11-20 to match the draft picker's separators): both
# model pickers group their entries Free Models, Regular
# Models, Uncensored Models. The class
# is data, never label text: a video model is uncensored when
# the same UNCENSORED_VIDEO_MODELS flag the gallery filter
# reads says so (the house Wan 2.2 carries that flag: open
# weights on our own worker, no provider moderation), and an
# image lane is uncensored when its pricing entry carries the
# matching flag. Everything else with a price is paid; the
# zero credit lanes (title cards, faceless shorts, the motion
# templates) are free and live in the studio page itself, not
# in these tables.
# The house image lane's display name (Jack, 2026-11-19): the
# lane runs Z-Image Turbo on the house worker, so it carries
# its real model's name everywhere the name prints (the image
# picker serves it from the config below, the gallery falls
# back to it). The lane runs on Kaggle free compute, so its
# real cost is $0 and it groups with the Free Models at a
# plain name with no tier marks, like the other free lanes
# (Jack, 2026-11-20).
HOUSE_IMAGE_NAME = "Z-Image Turbo"
HOUSE_IMAGE_LABEL = "Z-Image Turbo"


def model_picker_class(model_id: str) -> str:
    return ("uncensored" if model_id in UNCENSORED_VIDEO_MODELS
            else "paid")


def image_picker_class(lane_id: str) -> str:
    if lane_id == "house":
        # The house image lane (Z-Image Turbo) runs on Kaggle
        # free compute at a real cost of $0, so it groups as
        # free (Jack, 2026-11-20), the class the picker's Free
        # Models group reads.
        return "free"
    lane = pricing.IMAGE_LANES.get(lane_id) or {}
    if lane.get("free"):
        # A lane whose raw cost is $0 (the Cloudflare free
        # image lanes, 2026-11-20) groups as free, the class
        # the picker's Free Models group reads.
        return "free"
    return "uncensored" if lane.get("uncensored") else "paid"


def _image_size_rank(size: str) -> float:
    """Rank one image size so a lane's smallest size sorts
    first: K tiers by their number, pixel sizes by area in
    megapixels, anything else (the edit lane's "match") at 0.
    A shaped size ("1K-16:9") ranks at its tier, so a lane's
    smallest size stays its lowest tier's square."""
    head = size.split("-", 1)[0]
    if head.endswith("K"):
        try:
            return float(head[:-1])
        except ValueError:
            return 0.0
    if "x" in size:
        try:
            w, h = size.split("x", 1)
            return int(w) * int(h) / 1_000_000.0
        except ValueError:
            return 0.0
    return 0.0


def image_smallest_size(lane: dict) -> str:
    return min(lane["raw_cents"], key=_image_size_rank)


def image_picker_price_cents(lane_id: str) -> float:
    """The per image customer price a picker sorts by: the
    house lane's flat image price, or a shelf lane's customer
    price at its smallest size."""
    if lane_id == "house":
        return float(pricing.image_price_cents())
    lane = pricing.IMAGE_LANES[lane_id]
    _raw, debit = pricing.image_lane_price(
        lane_id, image_smallest_size(lane))
    return debit


# Image tier bands (Jack, 2026-11-19): the image shelf bands
# its $ marks on the per image customer price, $ up to 3c,
# $$ above 3c up to 4.5c, $$$ above 4.5c up to 10c, $$$$
# above 10c. (The video per second bands below are a
# separate scale.) The pickers read the tier as data from
# the config, never out of a label string.
IMAGE_TIER_BANDS_CENTS = (3.0, 4.5, 10.0)


def image_tier_for_price(price_cents):
    if price_cents is None:
        return None
    if price_cents <= IMAGE_TIER_BANDS_CENTS[0]:
        return 1
    if price_cents <= IMAGE_TIER_BANDS_CENTS[1]:
        return 2
    if price_cents <= IMAGE_TIER_BANDS_CENTS[2]:
        return 3
    return 4


def image_lane_tier(lane_id: str):
    """The lane's $ tier as data, from its picker price."""
    return image_tier_for_price(image_picker_price_cents(lane_id))


def image_lane_name(lane_id: str) -> str:
    """The lane's plain model name for the picker: the pricing
    label without its tier marks, which the config serves as
    their own field now."""
    return pricing.IMAGE_LANES[lane_id]["label"].split(" · ")[0]


