def _info_page(title: str, description: str, body: str) -> str:
    return (
        """<!doctype html><html lang="en"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>"""
        + title
        + """</title>
<meta name="description" content=\""""
        + description
        + """\">"""
        + _CSS
        + _INFO_CSS
        + _ICON_LINK
        + _PWA_HEAD
        + "\n</head><body><main>\n"
        + _INFO_HEADER
        + '\n<div class="legal">\n'
        + body
        + "\n</div>\n</main>\n"
        + _INFO_FOOTER
        + _PWA_SCRIPT
        + "\n</body></html>"
    )


